<template>
  <AppLoader v-if="isLoading" subject="staffing resource details" />
  <AppError
    v-else-if="error"
    :error="error"
    :title="error.statusCode === 404 ? 'Staffing contact not found' : 'Failed to load staffing resource details'"
    :to="error.statusCode === 404 ? { name: 'staffing-resources' } : undefined"
    :action-text="error.statusCode === 404 ? 'Back to Staffing Resources' : undefined"
  />
  <AppEmpty v-else-if="!data" subject="staffing resource details" />
  <section v-else class="flex flex-col gap-6">
    <PageTitle :title="`${[data.first_name, data.last_name].filter(Boolean).join(' ')} - Details`">
      <Badge :variant="getStaffingContactStatus(data).variant">
        {{ getStaffingContactStatus(data).label }}
      </Badge>
    </PageTitle>
    <div class="grid grid-cols-3 gap-4">
      <StaffingContactDetailsNavbar
        class="col-span-3"
        :show-create-note-button="!isNoteDraft && !data.note"
        :is-send-batch-loading="isSendBatchLoading"
        @create-note="isNoteDraft = true"
        @contact="onContact(data.email)"
      />
      <div class="col-span-3 xl:col-span-2 flex flex-col gap-4">
        <StaffingContactDetailsNote
          v-if="data.note || isNoteDraft"
          :email="data.email"
          :note="data.note"
          :is-note-draft="isNoteDraft"
          @update:is-note-draft="isNoteDraft = $event"
          @note-changed="refetch"
        />
        <StaffingContactDetailsRegisteredUser v-if="data.registered_user" :user="data.registered_user" />
        <StaffingContactDetailsInfo :data="data" />
        <StaffingContactDetailsRecruitment :data="data" />
        <StaffingContactDetailsReferredBy v-if="data.referred_by_user" :user="data.referred_by_user" />
        <StaffingContactDetailsProfessional :data="data" />
        <StaffingContactDetailsInteractions
          :interactions="interactionsData?.items ?? []"
          :total-count="interactionsData?.total_count ?? 0"
          :email="email"
          :is-loading="isInteractionsLoading"
          :error="interactionsError"
        />
        <StaffingContactDetailsInboundMessages
          v-if="data.inbound_messages.length"
          :messages="data.inbound_messages"
          :total="data.inbound_messages_total"
        />
      </div>
      <div class="col-span-3 xl:col-span-1 flex flex-col gap-4">
        <StaffingContactDetailsProjects :data="data" />
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import {
  getStaffingContactDetails,
  getStaffingContactInteractionList,
  type GetStaffingContactDetailsResponse,
  type GetStaffingContactInteractionListResponse,
} from '~/client';
import { getStaffingContactStatus } from '~/constants/staffing-contacts/staffingContactStatusConfig';
import { getSkippedContactReason } from '~/constants/recruitment/skippedContactReasonConfig';
import { useRecruitmentMessageSendBatch } from '~/mutations/recruitment/messages/sendBatch';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'staffing contact',
});

const route = useRoute('staffing-resources-email');
const email = computed(() => route.params.email);
const isNoteDraft = ref(false);

const { sendBatch, isSendBatchLoading } = useRecruitmentMessageSendBatch();

// One idempotency key per Message action: generated on click and reused if the send is retried after a failure,
// so a retry returns the original result rather than sending twice. Cleared once a send succeeds, so a later
// deliberate Message is a fresh action with a new key.
const sendKey = ref('');

async function onContact(contactEmail: string) {
  if (!sendKey.value) {
    sendKey.value = crypto.randomUUID();
  }
  const response = await sendBatch({ emails: [contactEmail], idempotency_key: sendKey.value }).catch(() => null);
  if (!response) return;
  sendKey.value = '';

  const skipped = response.skipped[0];
  const skippedDetail = skipped ? `This contact was skipped - ${getSkippedContactReason(skipped.reason).label}.` : '';
  showSendBatchResultToast(
    { createdCount: response.created_count, skippedCount: response.skipped.length },
    {
      allSent: { title: 'Message sent successfully' },
      partial: { title: 'Message sent successfully' },
      allSkipped: { title: 'Message not sent', description: skippedDetail },
    }
  );
  refetch();
}

const { data, error, isLoading, refetch } = useQuery({
  key: () => ['staffing-contact', email.value],
  query: (): Promise<GetStaffingContactDetailsResponse> =>
    getStaffingContactDetails({ composable: '$fetch', path: { email: email.value } }),
  enabled: () => !!email.value,
});

const {
  data: interactionsData,
  error: interactionsError,
  isLoading: isInteractionsLoading,
} = useQuery({
  key: () => ['staffing-contact-interactions', email.value],
  query: (): Promise<GetStaffingContactInteractionListResponse> =>
    getStaffingContactInteractionList({
      composable: '$fetch',
      path: { email: email.value },
      query: { page: 1, size: 5 },
    }),
  enabled: () => !!email.value,
});

useHead({
  title: computed(() =>
    data.value ? [data.value.first_name, data.value.last_name].filter(Boolean).join(' ') : 'Staffing Resource'
  ),
});
</script>
