import {
  editStaffingContactNote,
  type StaffingContactNoteEditRequest,
  type EditStaffingContactNoteResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useStaffingContactNoteEdit = defineMutation(() => {
  const { mutateAsync: staffingContactNoteEdit, asyncStatus } = useMutation({
    mutation: (vars: {
      email: string;
      form: StaffingContactNoteEditRequest;
    }): Promise<EditStaffingContactNoteResponse> =>
      editStaffingContactNote({
        composable: '$fetch',
        path: { email: vars.email },
        body: vars.form,
      }),
    onSuccess: () => {
      showToastSuccess('Note saved successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    staffingContactNoteEdit,
    isNoteEditLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
