import { setStaffingContactEmailUnsubscribe } from '~/client';
import type { SetStaffingContactEmailUnsubscribeResponse, StaffingContactDetailsResponse } from '~/client';

export const useSetEmailUnsubscribe = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<SetStaffingContactEmailUnsubscribeResponse> =>
      setStaffingContactEmailUnsubscribe({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, email_unsubscribed_at: new Date().toISOString() } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('Email unsubscribe set successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    setEmailUnsubscribe: mutateAsync,
    isSetEmailUnsubscribeLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
