import { setStaffingContactSmsSuppression } from '~/client';
import type { SetStaffingContactSmsSuppressionResponse, StaffingContactDetailsResponse } from '~/client';

export const useSetSmsSuppression = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<SetStaffingContactSmsSuppressionResponse> =>
      setStaffingContactSmsSuppression({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, sms_opted_out_at: new Date().toISOString() } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('SMS opt-out set successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    setSmsSuppression: mutateAsync,
    isSetSmsSuppressionLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
