<template>
  <Card>
    <CardHeader>
      <CardTitle>Contact Information</CardTitle>
    </CardHeader>
    <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <LabeledValue v-for="(item, index) in contactInfo" :key="index" :label="item.label" :value="item.value" />
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { StaffingContactDetailsResponse } from '~/client';

const props = defineProps<{
  data: StaffingContactDetailsResponse;
}>();

const contactInfo = computed(() => [
  { label: 'Email', value: props.data.email },
  { label: 'Full Name', value: [props.data.first_name, props.data.last_name].filter(Boolean).join(' ') },
  { label: 'Phone', value: props.data.phone_number },
  { label: 'Date of Birth', value: props.data.date_of_birth },
  { label: 'Address', value: props.data.address },
  { label: 'City', value: props.data.city },
  { label: 'State', value: props.data.state },
  { label: 'Zip Code', value: props.data.zip_code },
  { label: 'Military Status', value: props.data.military_status },
  {
    label: 'Additional Languages',
    value: props.data.additional_languages.length > 0 ? props.data.additional_languages.join(', ') : null,
  },
]);
</script>
