import { resumeStaffingContactRecruitment } from '~/client';
import type { ResumeStaffingContactRecruitmentResponse, StaffingContactDetailsResponse } from '~/client';

export const useResumeRecruitment = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<ResumeStaffingContactRecruitmentResponse> =>
      resumeStaffingContactRecruitment({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, recruitment_status: 'available' as const } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('Recruitment resumed successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    resumeRecruitment: mutateAsync,
    isResumeRecruitmentLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
