<template>
  <Card>
    <CardHeader>
      <CardTitle>Recruitment</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <LabeledValue label="Recruitment Status">
          <Badge :variant="recruitmentStatus.variant" size="sm">{{ recruitmentStatus.label }}</Badge>
        </LabeledValue>
        <LabeledValue label="General Messages" value-class="flex items-center gap-2">
          <span>{{ data.general_message_count.toString() }}</span>
          <Badge v-if="data.is_general_exhausted" variant="destructive" size="sm">Exhausted</Badge>
        </LabeledValue>
        <LabeledValue label="Project Messages" value-class="flex items-center gap-2">
          <span>{{ data.project_message_count.toString() }}</span>
          <Badge v-if="data.is_project_exhausted" variant="destructive" size="sm">Exhausted</Badge>
        </LabeledValue>
        <LabeledValue v-for="(item, index) in info" :key="index" :label="item.label" :value="item.value" />
      </div>

      <Separator />

      <div>
        <h4 class="text-sm font-medium text-muted-foreground mb-2">Suppression</h4>
        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledValue v-for="(item, index) in suppressionInfo" :key="index" :label="item.label" :value="item.value" />
          <LabeledValue label="SMS Delivery">
            <Badge v-if="data.sms_delivery_failing" variant="warning" size="sm">Failing</Badge>
            <span v-else>-</span>
          </LabeledValue>
          <LabeledValue label="Do Not Hire">
            <Badge v-if="data.do_not_hire" variant="destructive" size="sm">Do Not Hire</Badge>
            <span v-else>-</span>
          </LabeledValue>
        </div>
      </div>

      <template v-if="isAdmin">
        <Separator />

        <div class="flex flex-col gap-4">
          <ResetCountersDialog mode="single" :contacts="[data]" />

          <div class="flex flex-col divide-y divide-border">
            <div
              v-for="row in channels"
              :key="row.key"
              class="flex flex-col gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-start sm:justify-between"
            >
              <div class="flex flex-col gap-1">
                <div class="flex items-center gap-2">
                  <component :is="row.icon" class="size-4 text-muted-foreground" />
                  <span class="text-sm font-medium">{{ row.name }}</span>
                  <Badge :variant="row.stateVariant" size="sm">{{ row.stateLabel }}</Badge>
                </div>
                <p v-if="row.detail" class="text-xs text-muted-foreground">{{ row.detail }}</p>
              </div>

              <ConfirmationDialog
                v-if="row.action"
                :title="row.action.title"
                :description="row.action.description"
                :confirm-btn-text="row.action.confirmText"
                :confirm-btn-variant="row.action.confirmVariant"
                :is-confirm-loading="row.action.isLoading"
                @confirm="row.action.onConfirm"
              >
                <Button size="sm" variant="outline" :prepend-icon="row.action.icon" class="w-full sm:w-auto">
                  {{ row.action.label }}
                </Button>
              </ConfirmationDialog>
              <TooltipProvider v-else-if="row.blockedHint" :delay-duration="300">
                <Tooltip>
                  <TooltipTrigger as-child>
                    <span class="w-full sm:w-auto">
                      <Button size="sm" variant="ghost" disabled :prepend-icon="InfoIcon" class="w-full sm:w-auto">
                        Locked
                      </Button>
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>{{ row.blockedHint }}</TooltipContent>
                </Tooltip>
              </TooltipProvider>
            </div>
          </div>
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { InfoIcon } from 'lucide-vue-next';
import type { StaffingContactDetailsResponse } from '~/client';
import { getRecruitmentStatus } from '~/constants/staffing-contacts/recruitmentStatusConfig';
import type { ChannelRowActionKey } from '~/constants/staffing-contacts/recruitmentChannelRowsConfig';
import { buildRecruitmentChannelRows } from '~/utils/staffingContacts/buildRecruitmentChannelRows';
import { useClearSuppression } from '~/mutations/staffing-contacts/clearSuppression';
import { useClearSmsSuppression } from '~/mutations/staffing-contacts/clearSmsSuppression';
import { useSetEmailUnsubscribe } from '~/mutations/staffing-contacts/setEmailUnsubscribe';
import { useSetSmsSuppression } from '~/mutations/staffing-contacts/setSmsSuppression';
import { useStopRecruitment } from '~/mutations/staffing-contacts/stopRecruitment';
import { useResumeRecruitment } from '~/mutations/staffing-contacts/resumeRecruitment';

const props = defineProps<{
  data: StaffingContactDetailsResponse;
}>();

const { clearSuppression, isClearSuppressionLoading } = useClearSuppression();
const { clearSmsSuppression, isClearSmsSuppressionLoading } = useClearSmsSuppression();
const { setEmailUnsubscribe, isSetEmailUnsubscribeLoading } = useSetEmailUnsubscribe();
const { setSmsSuppression, isSetSmsSuppressionLoading } = useSetSmsSuppression();
const { stopRecruitment, isStopRecruitmentLoading } = useStopRecruitment();
const { resumeRecruitment, isResumeRecruitmentLoading } = useResumeRecruitment();
const { timezone, isAdmin } = useUserRole();

const recruitmentStatus = computed(() => getRecruitmentStatus(props.data.recruitment_status));

const info = computed(() => [
  {
    label: 'Last General Message',
    value: props.data.last_general_message_at
      ? formatDateTzToFormat(props.data.last_general_message_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
  {
    label: 'Last Project Message',
    value: props.data.last_project_message_at
      ? formatDateTzToFormat(props.data.last_project_message_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
  {
    label: 'Contact Timezone',
    value: props.data.timezone ?? null,
  },
]);

const suppressionInfo = computed(() => [
  {
    label: 'Email Unsubscribed',
    value: props.data.email_unsubscribed_at
      ? formatDateTzToFormat(props.data.email_unsubscribed_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
  {
    label: 'Spam Complaint',
    value: props.data.email_spam_complaint_at
      ? formatDateTzToFormat(props.data.email_spam_complaint_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
  {
    label: 'Hard Bounced',
    value: props.data.email_hard_bounced_at
      ? formatDateTzToFormat(props.data.email_hard_bounced_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
  {
    label: 'SMS Opted Out',
    value: props.data.sms_opted_out_at
      ? formatDateTzToFormat(props.data.sms_opted_out_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : null,
  },
]);

type ContactAction = (email: string) => Promise<unknown>;

function ignoreActionError(): void {
  // The mutation already showed the error toast.
}

async function runContactAction(action: ContactAction): Promise<void> {
  await action(props.data.email).catch(ignoreActionError);
}

function onClearSuppressionConfirm(): Promise<void> {
  return runContactAction(clearSuppression);
}

function onClearSmsSuppressionConfirm(): Promise<void> {
  return runContactAction(clearSmsSuppression);
}

function onSetEmailUnsubscribeConfirm(): Promise<void> {
  return runContactAction(setEmailUnsubscribe);
}

function onSetSmsSuppressionConfirm(): Promise<void> {
  return runContactAction(setSmsSuppression);
}

function onStopRecruitmentConfirm(): Promise<void> {
  return runContactAction(stopRecruitment);
}

function onResumeRecruitmentConfirm(): Promise<void> {
  return runContactAction(resumeRecruitment);
}

const actionWiring: Record<ChannelRowActionKey, { isLoading: { value: boolean }; onConfirm: () => Promise<void> }> = {
  setEmailUnsubscribe: { isLoading: isSetEmailUnsubscribeLoading, onConfirm: onSetEmailUnsubscribeConfirm },
  clearSuppression: { isLoading: isClearSuppressionLoading, onConfirm: onClearSuppressionConfirm },
  setSmsSuppression: { isLoading: isSetSmsSuppressionLoading, onConfirm: onSetSmsSuppressionConfirm },
  clearSmsSuppression: { isLoading: isClearSmsSuppressionLoading, onConfirm: onClearSmsSuppressionConfirm },
  stopRecruitment: { isLoading: isStopRecruitmentLoading, onConfirm: onStopRecruitmentConfirm },
  resumeRecruitment: { isLoading: isResumeRecruitmentLoading, onConfirm: onResumeRecruitmentConfirm },
};

const channels = computed(() =>
  buildRecruitmentChannelRows(props.data, (iso) =>
    formatDateTzToFormat(iso, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
  ).map((row) => ({
    ...row,
    action: row.action
      ? {
          ...row.action,
          isLoading: actionWiring[row.action.key].isLoading.value,
          onConfirm: actionWiring[row.action.key].onConfirm,
        }
      : null,
  }))
);
</script>
