import type { UserShortInfo } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface StaffingContactStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export function getStaffingContactStatus(contact: {
  registered_user?: UserShortInfo | null;
  user_id?: string | null;
  user_status?: string | null;
  contacts_count?: number;
}): StaffingContactStatusEntry {
  if (contact.user_status === 'blocked') return { label: 'Blocked', variant: 'destructive' };
  if (contact.user_status === 'deleted') return { label: 'Deleted', variant: 'default' };
  if (contact.registered_user?.id ?? contact.user_id) return { label: 'Registered', variant: 'success' };
  if (contact.contacts_count === undefined) return { label: 'Not Registered', variant: 'default' };
  if (contact.contacts_count === 0) return { label: 'Never contacted', variant: 'default' };
  if (contact.contacts_count === 1) return { label: 'Contacted once', variant: 'info' };
  return { label: `Contacted ${contact.contacts_count} times`, variant: 'info' };
}
