import { stopStaffingContactRecruitment } from '~/client';
import type { StaffingContactDetailsResponse, StopStaffingContactRecruitmentResponse } from '~/client';

export const useStopRecruitment = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<StopStaffingContactRecruitmentResponse> =>
      stopStaffingContactRecruitment({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, recruitment_status: 'stopped' as const } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('Recruitment stopped successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    stopRecruitment: mutateAsync,
    isStopRecruitmentLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
