import { clearStaffingContactSuppression } from '~/client';
import type { ClearStaffingContactSuppressionResponse, StaffingContactDetailsResponse } from '~/client';

export const useClearSuppression = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<ClearStaffingContactSuppressionResponse> =>
      clearStaffingContactSuppression({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, email_unsubscribed_at: null } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('Suppression cleared successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    clearSuppression: mutateAsync,
    isClearSuppressionLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
