import type { StaffingContactDetailsResponse } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';
import {
  channelRowMeta,
  channelRowActions,
  CLEAR_SMS_DESCRIPTION_BASE,
  CLEAR_SMS_DESCRIPTION_TAIL,
  CLEAR_SMS_INBOUND_POINTER,
  EMAIL_LOCK_HARD_BOUNCED,
  EMAIL_LOCK_SPAM_COMPLAINT,
  RECRUITMENT_LOCK_DO_NOT_HIRE,
  type ChannelRowKey,
  type ChannelRowActionConfig,
} from '~/constants/staffing-contacts/recruitmentChannelRowsConfig';
import { getRecruitmentStatus } from '~/constants/staffing-contacts/recruitmentStatusConfig';

export interface ChannelRowDescriptor {
  key: ChannelRowKey;
  name: string;
  icon: (typeof channelRowMeta)[ChannelRowKey]['icon'];
  stateLabel: string;
  stateVariant: BadgeVariants;
  detail: string | null;
  action: ChannelRowActionConfig | null;
  blockedHint: string | null;
}

export function buildRecruitmentChannelRows(
  data: StaffingContactDetailsResponse,
  formatTimestamp: (iso: string) => string
): ChannelRowDescriptor[] {
  const canClearSuppression =
    Boolean(data.email_unsubscribed_at) && !data.email_spam_complaint_at && !data.email_hard_bounced_at;
  const emailLockReason = data.email_hard_bounced_at ? EMAIL_LOCK_HARD_BOUNCED : EMAIL_LOCK_SPAM_COMPLAINT;

  const email: ChannelRowDescriptor = !data.email_unsubscribed_at
    ? {
        key: 'email',
        ...channelRowMeta.email,
        stateLabel: 'Subscribed',
        stateVariant: 'success',
        detail: null,
        action: channelRowActions.setEmailUnsubscribe,
        blockedHint: null,
      }
    : {
        key: 'email',
        ...channelRowMeta.email,
        stateLabel: 'Unsubscribed',
        stateVariant: 'destructive',
        detail: canClearSuppression ? `Since ${formatTimestamp(data.email_unsubscribed_at)}` : emailLockReason,
        action: canClearSuppression ? channelRowActions.clearSuppression : null,
        blockedHint: canClearSuppression ? null : emailLockReason,
      };

  const clearSmsDescription =
    CLEAR_SMS_DESCRIPTION_BASE +
    (data.inbound_messages.length ? CLEAR_SMS_INBOUND_POINTER : '') +
    CLEAR_SMS_DESCRIPTION_TAIL;

  const sms: ChannelRowDescriptor = !data.sms_opted_out_at
    ? {
        key: 'sms',
        ...channelRowMeta.sms,
        stateLabel: 'Opted-In',
        stateVariant: 'success',
        detail: null,
        action: channelRowActions.setSmsSuppression,
        blockedHint: null,
      }
    : {
        key: 'sms',
        ...channelRowMeta.sms,
        stateLabel: 'Opted-Out',
        stateVariant: 'destructive',
        detail: `Since ${formatTimestamp(data.sms_opted_out_at)}`,
        action: { ...channelRowActions.clearSmsSuppression, description: clearSmsDescription },
        blockedHint: null,
      };

  const recruitmentStatus = getRecruitmentStatus(data.recruitment_status);
  const canResumeRecruitment = data.recruitment_status === 'stopped' && !data.do_not_hire;

  const recruitment: ChannelRowDescriptor =
    data.recruitment_status !== 'stopped'
      ? {
          key: 'recruitment',
          ...channelRowMeta.recruitment,
          stateLabel: recruitmentStatus.label,
          stateVariant: recruitmentStatus.variant,
          detail: null,
          action: channelRowActions.stopRecruitment,
          blockedHint: null,
        }
      : {
          key: 'recruitment',
          ...channelRowMeta.recruitment,
          stateLabel: recruitmentStatus.label,
          stateVariant: recruitmentStatus.variant,
          detail: null,
          action: canResumeRecruitment ? channelRowActions.resumeRecruitment : null,
          blockedHint: canResumeRecruitment ? null : RECRUITMENT_LOCK_DO_NOT_HIRE,
        };

  return [email, sms, recruitment];
}
