<template>
  <Alert>
    <Info class="mt-2.5" />
    <AlertTitle class="flex flex-wrap items-center justify-between min-h-9 gap-2">
      Note
      <div v-if="!isEditing" class="float-right flex flex-row gap-2">
        <template v-if="note">
          <Button variant="outline" :prepend-icon="Pencil" @click="startEditing">Edit</Button>
          <ConfirmationDialog
            title="Remove note?"
            description="Are you sure you want to remove this note?"
            confirm-btn-variant="destructive"
            confirm-btn-text="Remove"
            @confirm="onRemoveNote"
          >
            <Button variant="outline" :prepend-icon="Trash" :loading="isNoteRemoveLoading">Remove</Button>
          </ConfirmationDialog>
        </template>
      </div>
    </AlertTitle>
    <AlertDescription>
      <form v-if="isEditing" class="w-full mt-2" @submit="onNoteSubmit">
        <FormField v-slot="{ componentField }" name="note">
          <FormItem>
            <FormControl>
              <Textarea placeholder="Put here any text" class="resize-none" v-bind="componentField" />
            </FormControl>
            <FormDescription class="text-wrap">
              This note is visible to other managers and administrators
            </FormDescription>
            <FormMessage />
          </FormItem>
        </FormField>
        <div class="flex flex-row gap-2 justify-end mt-2">
          <Button variant="outline" type="button" @click="cancelEditing">Cancel</Button>
          <Button type="submit" :loading="isNoteEditLoading">Save</Button>
        </div>
      </form>
      <template v-else-if="note">
        <AppMarkdown :markdown="note.text" />
        <p class="text-xs text-muted-foreground mt-2">
          <template v-if="note.updated_by">Updated by <InlineEntityUser :user="note.updated_by" /> on</template>
          <template v-else>Updated on</template>
          {{ formatDateTzToFormat(note.updated_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
        </p>
      </template>
    </AlertDescription>
  </Alert>
</template>

<script setup lang="ts">
import { Alert, AlertDescription, AlertTitle } from '~/components/ui/alert';
import { Info, Pencil, Trash } from 'lucide-vue-next';
import { FormControl, FormDescription, FormField, FormItem, FormMessage } from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import * as z from 'zod';
import type { StaffingContactNoteInfo } from '~/client';
import { useStaffingContactNoteEdit } from '~/mutations/staffing-contacts/notes/edit';
import { useStaffingContactNoteRemove } from '~/mutations/staffing-contacts/notes/remove';

const props = defineProps<{
  email: string;
  note: StaffingContactNoteInfo | null;
  isNoteDraft: boolean;
}>();

const emit = defineEmits<{
  (e: 'update:isNoteDraft', value: boolean): void;
  (e: 'noteChanged'): void;
}>();

const isEditing = ref(props.isNoteDraft);

watch(
  () => props.isNoteDraft,
  (val) => {
    if (val) isEditing.value = true;
  }
);

const formSchema = toTypedSchema(
  z.object({
    note: z.string().nonempty('Text is required'),
  })
);

const { handleSubmit, setFieldValue } = useForm({
  validationSchema: formSchema,
});

function startEditing() {
  setFieldValue('note', props.note?.text ?? '');
  isEditing.value = true;
}

function cancelEditing() {
  isEditing.value = false;
  emit('update:isNoteDraft', false);
}

const { staffingContactNoteEdit, isNoteEditLoading } = useStaffingContactNoteEdit();
const onNoteSubmit = handleSubmit(async ({ note }) => {
  await staffingContactNoteEdit({ email: props.email, form: { content: note } });
  isEditing.value = false;
  emit('update:isNoteDraft', false);
  emit('noteChanged');
});

const { staffingContactNoteRemove, isNoteRemoveLoading } = useStaffingContactNoteRemove();
async function onRemoveNote() {
  await staffingContactNoteRemove({ email: props.email });
  emit('update:isNoteDraft', false);
  emit('noteChanged');
}

const { timezone } = useUserRole();
</script>
