import { removeStaffingContactNote, type RemoveStaffingContactNoteResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useStaffingContactNoteRemove = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { email: string }): Promise<RemoveStaffingContactNoteResponse> =>
      removeStaffingContactNote({
        composable: '$fetch',
        path: { email: vars.email },
      }),
    onSuccess: () => {
      showToastSuccess('Note removed successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    staffingContactNoteRemove: mutateAsync,
    isNoteRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
