import { clearStaffingContactSmsSuppression } from '~/client';
import type { ClearStaffingContactSmsSuppressionResponse, StaffingContactDetailsResponse } from '~/client';

export const useClearSmsSuppression = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (email: string): Promise<ClearStaffingContactSmsSuppressionResponse> =>
      clearStaffingContactSmsSuppression({
        composable: '$fetch',
        path: { email },
      }),
    onSuccess: (_, email) => {
      queryCache.setQueryData(['staffing-contact', email], (oldData?: StaffingContactDetailsResponse) =>
        oldData ? { ...oldData, sms_opted_out_at: null } : oldData
      );
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('SMS suppression cleared successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    clearSmsSuppression: mutateAsync,
    isClearSmsSuppressionLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
